"""Rule-based resume improvement suggestions.

IMPORTANT: these suggestions come from simple, transparent rules (missing skills,
resume length, presence of sections, numbers, action verbs). They are NOT
generated by an AI model and are not a substitute for a human reviewer.
"""

from __future__ import annotations

import re

from src.skill_extractor import group_by_category

RULE_BASED_NOTE = (
    "These suggestions are generated by simple, rule-based checks - not by an AI model "
    "or an expert reviewer. Treat them as a starting point, and only add skills you "
    "genuinely have."
)

ACTION_VERBS = (
    "built", "developed", "designed", "implemented", "created", "led", "improved",
    "deployed", "optimized", "optimised", "automated", "analyzed", "analysed",
    "reduced", "increased", "launched", "managed", "trained", "evaluated", "wrote",
)

SECTION_PATTERNS = {
    "Education": r"^\s*(education|academic)",
    "Experience": r"^\s*(experience|work experience|internship|employment)",
    "Projects": r"^\s*(projects?|personal projects?)",
    "Skills": r"^\s*(skills|technical skills|key skills)",
}


def _count_numbers(text: str) -> int:
    """Count quantified results such as '84%', '$5k' or '50,000'."""
    return len(re.findall(r"\d+(?:[.,]\d+)?\s*%|\$\s?\d|\b\d{2,}(?:,\d{3})*\b", text))


def generate_recommendations(analysis: dict, resume_text: str, skills_db: dict) -> list[dict]:
    """Return a list of ``{"priority", "area", "suggestion"}`` dictionaries."""
    if not isinstance(resume_text, str):
        raise TypeError("resume_text must be a string.")

    items: list[dict] = []
    missing = analysis.get("missing", [])
    score = analysis.get("score", 0.0)
    words = len(resume_text.split())

    # 1. Missing skills, grouped by category
    if missing:
        priority = "High" if len(missing) >= 3 else "Medium"
        for category, skills in group_by_category(missing, skills_db).items():
            items.append({
                "priority": priority,
                "area": f"Skill gap - {category}",
                "suggestion": (
                    f"The job mentions {', '.join(skills)}, which your resume does not. "
                    "If you have real experience, add it to your Skills section and show it "
                    "in a project or experience bullet. If not, a small hands-on project "
                    "would be a credible way to start."
                ),
            })
    elif analysis.get("job_skills"):
        items.append({
            "priority": "Low",
            "area": "Skill gap",
            "suggestion": "Your resume mentions every skill from the dictionary that the job lists. "
                          "Make sure each one is backed by a concrete example.",
        })
    else:
        items.append({
            "priority": "Low",
            "area": "Skill detection",
            "suggestion": "No known skills were found in the job description. It may use terms that "
                          "are not in data/skills.json - you can add them to that file.",
        })

    # 2. Overall wording similarity
    if score < 10:
        items.append({
            "priority": "Medium",
            "area": "Wording",
            "suggestion": "Your resume shares little vocabulary with the job description. Where it is "
                          "truthful, reuse the job's terminology for tools, responsibilities and "
                          "domain concepts in your summary and bullet points.",
        })

    # 3. Length
    if words < 150:
        items.append({
            "priority": "High",
            "area": "Length",
            "suggestion": f"Your resume has only about {words} words. Add detail about projects, "
                          "internships, coursework and results.",
        })
    elif words > 1000:
        items.append({
            "priority": "Medium",
            "area": "Length",
            "suggestion": f"Your resume has about {words} words. Aim for one page (two at most) "
                          "and keep only the most relevant items.",
        })

    # 4. Quantified achievements
    if _count_numbers(resume_text) < 2:
        items.append({
            "priority": "Medium",
            "area": "Measurable impact",
            "suggestion": "Few numbers were found. Add metrics where you can, such as dataset size, "
                          "accuracy, time saved, users or percentage improvements.",
        })

    # 5. Standard sections
    missing_sections = [
        name for name, pattern in SECTION_PATTERNS.items()
        if not re.search(pattern, resume_text, flags=re.IGNORECASE | re.MULTILINE)
    ]
    if missing_sections:
        items.append({
            "priority": "Medium",
            "area": "Structure",
            "suggestion": "Section headings not detected: " + ", ".join(missing_sections) +
                          ". Clear headings help both people and applicant tracking systems.",
        })

    # 6. Action verbs
    lowered = resume_text.lower()
    verb_hits = sum(1 for verb in ACTION_VERBS if re.search(rf"\b{verb}\b", lowered))
    if verb_hits < 3:
        items.append({
            "priority": "Low",
            "area": "Action verbs",
            "suggestion": "Start bullet points with strong action verbs such as built, developed, "
                          "implemented, deployed or improved.",
        })

    order = {"High": 0, "Medium": 1, "Low": 2}
    items.sort(key=lambda item: order[item["priority"]])
    return items
